  application:
    name: payraise
  datasource:
    url: jdbc:postgresql://localhost:5432/payroll
    username: ${DB_USERNAME:payroll_user}
    password: ${DB_PASSWORD:payroll_pass}
    driver-class-name: org.postgresql.Driver
    hikari:
      maximum-pool-size: 10
      minimum-idle: 2
      connection-timeout: 30000
  jpa:
    hibernate:
      ddl-auto: validate
    show-sql: false
    properties:
      hibernate:
        dialect: org.hibernate.dialect.PostgreSQLDialect
        format_sql: true
  flyway:
    enabled: true
    locations: classpath:db/migration
  batch:
    job:
      enabled: false          # Jobs started programmatically, not on startup
    jdbc:
      initialize-schema: always

payraise:
  input-file: data/input/employees.dat
  output-file: data/output/employees_raised.dat
  chunk-size: 100

logging:
  level:
    com.modernized.payraise: INFO
    org.springframework.batch: INFO

