-- Mirrors the EMPREC copybook layout assumed from PAYRAISE context:
-- EMP-ID      PIC 9(05)
-- EMP-NAME    PIC X(30)
-- EMP-DEPT    PIC X(08)
-- EMP-SALARY  PIC 9(07)V99  (stored as NUMERIC(9,2))

CREATE TABLE IF NOT EXISTS employees (
    emp_id          BIGINT          PRIMARY KEY,
    emp_name        VARCHAR(30)     NOT NULL,
    emp_dept        VARCHAR(8)      NOT NULL,
    emp_salary      NUMERIC(9, 2)   NOT NULL,
    salary_updated  BOOLEAN         NOT NULL DEFAULT FALSE,
    updated_at      TIMESTAMP WITH TIME ZONE
);

CREATE INDEX IF NOT EXISTS idx_employees_dept ON employees (emp_dept);

