package com.modernized.payraise;

import com.modernized.payraise.job.PayRaiseJob;
import com.modernized.payraise.dto.PayRaiseResult;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.CommandLineRunner;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;

@SpringBootApplication
public class PayraiseApplication {

    private static final Logger log = LoggerFactory.getLogger(PayraiseApplication.class);

    public static void main(String[] args) {
        SpringApplication.run(PayraiseApplication.class, args);
    }

    /**
     * Entry point that mirrors the COBOL MAIN-PARA:
     *   OPEN INPUT EMP-FILE OUTPUT OUT-FILE
     *   PERFORM UNTIL END-OF-FILE ... APPLY-RAISE
     *   CLOSE EMP-FILE OUT-FILE
     *   DISPLAY summary
     *   STOP RUN
     */
    @Bean
    public CommandLineRunner run(PayRaiseJob payRaiseJob) {
        return args -> {
            PayRaiseResult result = payRaiseJob.execute();
            // Mirrors: DISPLAY "PAYRAISE: " WS-COUNT " RECORDS UPDATED, "
            //                  "TOTAL INCREASE " WS-DISP-INCREASE
            log.info("PAYRAISE: {} RECORDS UPDATED, TOTAL INCREASE {}",
                    result.recordsUpdated(),
                    result.formattedTotalIncrease());
        };
    }
}

