package com.modernized.payraise.model;

import jakarta.persistence.*;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;
import lombok.ToString;

import java.math.BigDecimal;
import java.time.OffsetDateTime;

/**
 * JPA entity that corresponds to the EMPREC copybook fields used in PAYRAISE:
 *   EMP-ID     PIC 9(05)
 *   EMP-NAME   PIC X(30)
 *   EMP-DEPT   PIC X(08)
 *   EMP-SALARY PIC 9(07)V99
 */
@Entity
@Table(name = "employees")
@Getter
@Setter
@NoArgsConstructor
@ToString
public class Employee {

    @Id
    @Column(name = "emp_id", nullable = false)
    private Long empId;

    @Column(name = "emp_name", nullable = false, length = 30)
    private String empName;

    /**
     * Matches EMP-DEPT PIC X(08).
     * Used by APPLY-RAISE EVALUATE block: "IT", "FINANCE", "SALES", OTHER.
     */
    @Column(name = "emp_dept", nullable = false, length = 8)
    private String empDept;

    /**
     * Matches EMP-SALARY PIC 9(07)V99.
     * NUMERIC(9,2) in PostgreSQL preserves exact decimal arithmetic.
     */
    @Column(name = "emp_salary", nullable = false, precision = 9, scale = 2)
    private BigDecimal empSalary;

    @Column(name = "salary_updated", nullable = false)
    private boolean salaryUpdated = false;

    @Column(name = "updated_at")
    private OffsetDateTime updatedAt;
}

