package com.modernized.payraise.repository;

import com.modernized.payraise.model.Employee;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.util.List;

@Repository
public interface EmployeeRepository extends JpaRepository<Employee, Long> {

    /**
     * Paginated fetch – mirrors READ loop (PERFORM UNTIL END-OF-FILE).
     * Processes all employees regardless of department.
     */
    Page<Employee> findAll(Pageable pageable);

    /**
     * Bulk update salary for a specific department using the raise multiplier.
     * Mirrors: COMPUTE EMP-SALARY ROUNDED = EMP-SALARY * (1 + WS-PCT)
     *
     * @param dept       department code (e.g. "IT")
     * @param multiplier (1 + raise percentage) e.g. 1.08 for IT
     * @return number of rows updated
     */
    @Modifying
    @Query(value = """
            UPDATE employees
               SET emp_salary      = ROUND(emp_salary * :multiplier, 2),
                   salary_updated  = TRUE,
                   updated_at      = NOW()
             WHERE TRIM(emp_dept)  = :dept
               AND salary_updated  = FALSE
            """, nativeQuery = true)
    int applyRaiseByDept(@Param("dept") String dept,
                         @Param("multiplier") BigDecimal multiplier);

    /**
     * Bulk update for all departments not explicitly listed (OTHER branch).
     * Mirrors COBOL WHEN OTHER MOVE .04 TO WS-PCT
     */
    @Modifying
    @Query(value = """
            UPDATE employees
               SET emp_salary      = ROUND(emp_salary * :multiplier, 2),
                   salary_updated  = TRUE,
                   updated_at      = NOW()
             WHERE TRIM(emp_dept) NOT IN ('IT', 'FINANCE', 'SALES')
               AND salary_updated  = FALSE
            """, nativeQuery = true)
    int applyRaiseForOtherDepts(@Param("multiplier") BigDecimal multiplier);

    /**
     * Sum of all salary increases applied in this run.
     * Mirrors: WS-TOTAL-INCREASE + EMP-SALARY - WS-OLD-SALARY
     */
    @Query(value = """
            SELECT COALESCE(SUM(emp_salary - (emp_salary / :multiplier)), 0)
              FROM employees
             WHERE salary_updated = TRUE
            """, nativeQuery = true)
    BigDecimal sumSalaryIncrease(@Param("multiplier") BigDecimal multiplier);

    /** Count of employees whose raise was applied (salary_updated = TRUE). */
    long countBySalaryUpdatedTrue();

    /** Retrieve updated employees for writing the output file. */
    List<Employee> findBySalaryUpdatedTrue();

    /** Reset flag between runs (utility – not part of original COBOL logic). */
    @Modifying
    @Query("UPDATE Employee e SET e.salaryUpdated = FALSE, e.updatedAt = NULL")
    void resetSalaryUpdatedFlag();
}

