package com.modernized.payraise.service;

import com.modernized.payraise.model.Employee;
import com.modernized.payraise.repository.EmployeeRepository;
import lombok.RequiredArgsConstructor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

/**
 * Service that faithfully reproduces the APPLY-RAISE paragraph logic:
 *
 *   EVALUATE EMP-DEPT
 *       WHEN "IT"         MOVE .08 TO WS-PCT
 *       WHEN "FINANCE"    MOVE .06 TO WS-PCT
 *       WHEN "SALES"      MOVE .05 TO WS-PCT
 *       WHEN OTHER        MOVE .04 TO WS-PCT
 *   END-EVALUATE
 *   COMPUTE EMP-SALARY ROUNDED = EMP-SALARY * (1 + WS-PCT)
 *   COMPUTE WS-TOTAL-INCREASE  = WS-TOTAL-INCREASE + EMP-SALARY - WS-OLD-SALARY
 */
@Service
@RequiredArgsConstructor
public class PayRaiseService {

    private static final Logger log = LoggerFactory.getLogger(PayRaiseService.class);

    // Raise percentages – mirrors COBOL EVALUATE WHEN constants
    private static final BigDecimal PCT_IT      = new BigDecimal("0.08"); // 8%
    private static final BigDecimal PCT_FINANCE = new BigDecimal("0.06"); // 6%
    private static final BigDecimal PCT_SALES   = new BigDecimal("0.05"); // 5%
    private static final BigDecimal PCT_OTHER   = new BigDecimal("0.04"); // 4%
    private static final BigDecimal ONE         = BigDecimal.ONE;

    private final EmployeeRepository employeeRepository;

    /**
     * Applies department-based raises in bulk – one UPDATE per department.
     * Returns total number of records updated (WS-COUNT equivalent).
     */
    @Transactional
    public int applyRaises() {
        int count = 0;

        // WHEN "IT" MOVE .08 TO WS-PCT
        count += applyDeptRaise("IT", PCT_IT);
        // WHEN "FINANCE" MOVE .06 TO WS-PCT
        count += applyDeptRaise("FINANCE", PCT_FINANCE);
        // WHEN "SALES" MOVE .05 TO WS-PCT
        count += applyDeptRaise("SALES", PCT_SALES);
        // WHEN OTHER MOVE .04 TO WS-PCT
        count += applyOtherDeptRaise(PCT_OTHER);

        log.info("PayRaiseService: {} employee records updated", count);
        return count;
    }

    /**
     * Applies raise for a named department.
     * Multiplier = 1 + WS-PCT  (e.g. 1.08 for IT)
     */
    private int applyDeptRaise(String dept, BigDecimal pct) {
        BigDecimal multiplier = ONE.add(pct);
        int updated = employeeRepository.applyRaiseByDept(dept, multiplier);
        log.debug("Department [{}]: {} records raised by {}%", dept, updated,
                pct.multiply(new BigDecimal("100")).toPlainString());
        return updated;
    }

    /**
     * Applies raise for all OTHER departments.
     * Multiplier = 1 + 0.04 = 1.04
     */
    private int applyOtherDeptRaise(BigDecimal pct) {
        BigDecimal multiplier = ONE.add(pct);
        int updated = employeeRepository.applyRaiseForOtherDepts(multiplier);
        log.debug("Department [OTHER]: {} records raised by {}%", updated,
                pct.multiply(new BigDecimal("100")).toPlainString());
        return updated;
    }

    /**
     * Computes total salary increase across all updated employees.
     *
     * Mirrors: WS-TOTAL-INCREASE = WS-TOTAL-INCREASE + EMP-SALARY - WS-OLD-SALARY
     *
     * Because the bulk updates do not preserve per-row old salary, we compute the
     * increase as:  new_salary - new_salary / multiplier  per department.
     * This is mathematically equivalent to new_salary - old_salary when
     * new_salary = old_salary * multiplier.
     *
     * For multi-department accuracy we calculate per-department then sum.
     */
    @Transactional(readOnly = true)
    public BigDecimal calculateTotalIncrease() {
        BigDecimal total = BigDecimal.ZERO;
        total = total.add(calculateDeptIncrease("IT",      PCT_IT));
        total = total.add(calculateDeptIncrease("FINANCE",  PCT_FINANCE));
        total = total.add(calculateDeptIncrease("SALES",    PCT_SALES));
        total = total.add(calculateOtherDeptIncrease(PCT_OTHER));
        return total.setScale(2, RoundingMode.HALF_UP);
    }

    private BigDecimal calculateDeptIncrease(String dept, BigDecimal pct) {
        BigDecimal multiplier = ONE.add(pct);
        // increase per employee = new_salary - (new_salary / multiplier)
        // SUM over all updated employees in dept
        return employeeRepository.findBySalaryUpdatedTrue().stream()
                .filter(e -> dept.equalsIgnoreCase(e.getEmpDept().trim()))
                .map(e -> e.getEmpSalary()
                           .subtract(e.getEmpSalary()
                                      .divide(multiplier, 10, RoundingMode.HALF_UP)))
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(2, RoundingMode.HALF_UP);
    }

    private BigDecimal calculateOtherDeptIncrease(BigDecimal pct) {
        BigDecimal multiplier = ONE.add(pct);
        List<String> named = List.of("IT", "FINANCE", "SALES");
        return employeeRepository.findBySalaryUpdatedTrue().stream()
                .filter(e -> !named.contains(e.getEmpDept().trim().toUpperCase()))
                .map(e -> e.getEmpSalary()
                           .subtract(e.getEmpSalary()
                                      .divide(multiplier, 10, RoundingMode.HALF_UP)))
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(2, RoundingMode.HALF_UP);
    }
}

// ----- src/main/java/com/modernized/payraise/job/PayRaiseJob.java -----
package com.modernized.payraise.job;

import com.modernized.payraise.dto.PayRaiseResult;
import com.modernized.payraise.model.Employee;
import com.modernized.payraise.repository.EmployeeRepository;
import com.modernized.payraise.service.PayRaiseService;
import lombok.RequiredArgsConstructor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Transactional;

import java.io.BufferedWriter;
import java.io.IOException;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.List;

/**
 * Orchestrates the full PAYRAISE job, mirroring MAIN-PARA:
 *
 *   OPEN INPUT EMP-FILE OUTPUT OUT-FILE
 *   PERFORM UNTIL END-OF-FILE
 *       READ EMP-FILE
 *           AT END SET END-OF-FILE TO TRUE
 *           NOT AT END PERFORM APPLY-RAISE
 *       END-READ
 *   END-PERFORM
 *   CLOSE EMP-FILE OUT-FILE
 *   DISPLAY summary
 *   STOP RUN
 */
@Component
@RequiredArgsConstructor
public class PayRaiseJob {

    private static final Logger log = LoggerFactory.getLogger(PayRaiseJob.class);

    private final PayRaiseService payRaiseService;
    private final EmployeeRepository employeeRepository;

    @Value("${payraise.output-file:data/output/employees_raised.dat}")
    private String outputFilePath;

    /**
     * Main execution – equivalent to MAIN-PARA.
     *
     * @return PayRaiseResult containing WS-COUNT and WS-TOTAL-INCREASE.
     */
    @Transactional
    public PayRaiseResult execute() {
        log.info("PAYRAISE job starting");

        // PERFORM UNTIL END-OF-FILE ... APPLY-RAISE (bulk raise via service)
        int recordsUpdated = payRaiseService.applyRaises();

        // WS-TOTAL-INCREASE accumulation (mirrors running total in APPLY-RAISE)
        BigDecimal totalIncrease = payRaiseService.calculateTotalIncrease();

        // WRITE OUT-RECORD FROM EMP-RECORD  (output file)
        List<Employee> updatedEmployees = employeeRepository.findBySalaryUpdatedTrue();
        writeOutputFile(updatedEmployees);

        // Build result – mirrors WS-COUNT and WS-DISP-INCREASE
        PayRaiseResult result = new PayRaiseResult(recordsUpdated, totalIncrease);
        log.info("PAYRAISE job finished: {}", result);
        return result;
    }

    /**
     * Writes output flat file matching OUT-FILE / OUT-RECORD PIC X(54).
     * Each record is fixed-width 54 characters, mirroring WRITE OUT-RECORD FROM EMP-RECORD.
     *
     * Layout (54 chars total, matches assumed EMPREC copybook):
     *   Cols  1- 5  : EMP-ID    (5 digits, zero-padded)
     *   Cols  6-35  : EMP-NAME  (30 chars, space-padded)
     *   Cols 36-43  : EMP-DEPT  (8 chars, space-padded)
     *   Cols 44-54  : EMP-SALARY (9 digits + decimal = 11 chars: NNNNNNN.NN)
     */
    private void writeOutputFile(List<Employee> employees) {
        Path outputPath = Paths.get(outputFilePath);
        try {
            Files.createDirectories(outputPath.getParent());
        } catch (IOException e) {
            log.warn("Could not create output directories: {}", e.getMessage());
        }

        try (BufferedWriter writer = Files.newBufferedWriter(
                outputPath,
                StandardCharsets.UTF_8,
                StandardOpenOption.CREATE,
                StandardOpenOption.TRUNCATE_EXISTING)) {

            for (Employee emp : employees) {
                String record = formatRecord(emp);
                writer.write(record);
                writer.newLine();
            }
            log.info("Output file written: {} ({} records)", outputFilePath, employees.size());

        } catch (IOException e) {
            throw new RuntimeException("Failed to write output file: " + outputFilePath, e);
        }
    }

    /**
     * Formats a single Employee into a 54-character fixed-width record.
     * Mirrors: OUT-RECORD PIC X(54)
     */
    private String formatRecord(Employee emp) {
        // EMP-ID: 5 digits zero-padded
        String id = String.format("%05d", emp.getEmpId());

        // EMP-NAME: 30 chars space-padded / truncated
        String name = String.format("%-30s",
                emp.getEmpName() != null ? emp.getEmpName() : "");
        if (name.length() > 30) name = name.substring(0, 30);

        // EMP-DEPT: 8 chars space-padded / truncated
        String dept = String.format("%-8s",
                emp.getEmpDept() != null ? emp.getEmpDept() : "");
        if (dept.length() > 8) dept = dept.substring(0, 8);

        // EMP-SALARY: 9(07)V99 => "NNNNNNN.NN" (11 chars)
        String salary = String.format("%011.2f",
                emp.getEmpSalary() != null ? emp.getEmpSalary() : BigDecimal.ZERO);

        // Total: 5 + 30 + 8 + 11 = 54
        return id + name + dept + salary;
    }
}

