package com.modernized.payraise.dto;

import java.math.BigDecimal;
import java.text.DecimalFormat;

/**
 * Immutable result DTO.
 * recordsUpdated  -> WS-COUNT    PIC 9(03)
 * totalIncrease   -> WS-TOTAL-INCREASE PIC 9(09)V99
 * formattedTotalIncrease() -> WS-DISP-INCREASE PIC ZZZ,ZZZ,ZZ9.99
 */
public record PayRaiseResult(int recordsUpdated, BigDecimal totalIncrease) {

    /**
     * Formats total increase using the COBOL edit mask:
     * WS-DISP-INCREASE PIC ZZZ,ZZZ,ZZ9.99
     * Leading zeros are suppressed; comma-separated thousands; 2 decimal places.
     */
    public String formattedTotalIncrease() {
        if (totalIncrease == null) {
            return "          0.00";
        }
        DecimalFormat df = new DecimalFormat("###,###,##0.00");
        return df.format(totalIncrease);
    }

    @Override
    public String toString() {
        return String.format("PayRaiseResult{recordsUpdated=%d, totalIncrease=%s}",
                recordsUpdated, formattedTotalIncrease());
    }
}

