package com.modernized.payraise.config;

import org.springframework.boot.autoconfigure.domain.EntityScan;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.jpa.repository.config.EnableJpaRepositories;
import org.springframework.transaction.annotation.EnableTransactionManagement;

@Configuration
@EnableTransactionManagement
@EnableJpaRepositories(basePackages = "com.modernized.payraise.repository")
@EntityScan(basePackages = "com.modernized.payraise.model")
public class DataSourceConfig {
    // DataSource, EntityManagerFactory and TransactionManager are
    // auto-configured by Spring Boot from application.yml properties.
    // This class centralises JPA scanning annotations.
}
